"@DatabaseTest
class MensagemAdminControllerIntegrationTest extends RestAssuredMockMvcTest {

    private static final String BASE_URL = "/api/admin/mensagens";
    private final MensagemInputITDtoFactory mensagemInputITDtoFactory = new MensagemInputITDtoFactory();
    private final BridgeFaker faker = new BridgeFaker();

    @Autowired
    private InstituicaoFactory instituicaoFactory;

    @Autowired
    private DAO dao;

    @Autowired
    private LDAPJwtFactory ldapJwtFactory;

    @Test
    @DisplayName("Deve criar mensagem inativa com dados válidos")
    void storeMensagemInativaExpectSuccess() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(1);
            m.instituicaoIds.set(List.of());
            m.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
                .formParam("isModifiedFile", mensagemInputDto.getIsModifiedFile())
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());
    }

    @Test
    @DisplayName("Deve criar mensagem ativa para instituições específicas com dados válidos")
    void storeMensagemAtivaParaInstituicoesExpectSuccess() {
        var instituicao1 = this.instituicaoFactory.createRandom();
        var instituicao2 = this.instituicaoFactory.createRandom();

        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(2);
            m.instituicaoIds.set(List.of(instituicao1.getId(), instituicao2.getId()));
            m.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .multiPart("instituicaoIds", String.valueOf(instituicao1.getId()))
                .multiPart("instituicaoIds", String.valueOf(instituicao2.getId()))
                .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
                .formParam("isModifiedFile", mensagemInputDto.getIsModifiedFile())
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        var storedMensagemInstituicoes = this.dao.queryFactory()
                .selectFrom(mensagemInstituicao)
                .where(mensagemInstituicao.mensagemId.eq(storedMensagemId))
                .fetch();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());
        assertThat(storedMensagemInstituicoes).hasSize(2);
        assertThat(storedMensagemInstituicoes)
                .extracting("instituicaoId")
                .containsExactlyInAnyOrder(instituicao1.getId(), instituicao2.getId());
    }

    @Test
    @DisplayName("Deve criar mensagem ativa para todos os estudantes com lista de instituições vazia")
    void storeMensagemAtivaParaTodosExpectSuccess() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(2);
            m.instituicaoIds.set(List.of());
            m.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
                .formParam("isModifiedFile", mensagemInputDto.getIsModifiedFile())
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        var storedMensagemInstituicoes = this.dao.queryFactory()
                .selectFrom(mensagemInstituicao)
                .where(mensagemInstituicao.mensagemId.eq(storedMensagemId))
                .fetch();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());
        assertThat(storedMensagemInstituicoes).isEmpty();
    }

    @Test
    @DisplayName("Não deve criar mensagem sem autorização")
    void storeMensagemWithoutAuthorizationExpectUnauthorized() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(1);
            m.instituicaoIds.set(List.of());
            m.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
        });

        given()
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
                .formParam("isModifiedFile", mensagemInputDto.getIsModifiedFile())
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(401);
    }
}"

"@DatabaseTest
class MensagemAdminControllerIntegrationTest extends RestAssuredMockMvcTest {

    private static final String BASE_URL = "/api/admin/mensagens";
    private final MensagemInputITDtoFactory mensagemInputITDtoFactory = new MensagemInputITDtoFactory();
    private final BridgeFaker faker = new BridgeFaker();

    @Autowired
    private InstituicaoFactory instituicaoFactory;

    @Autowired
    private DAO dao;

    @Autowired
    private LDAPJwtFactory ldapJwtFactory;

    @Test
    @DisplayName("Deve criar mensagem ativa para todas as instituições com dados válidos")
    void storeMensagemAtivaParaTodosExpectSuccess() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(2);
            m.instituicaoIds.set(List.of());
            m.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
            m.descricao.set("<p>Mensagem com <strong>HTML</strong></p>");
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .formParam("isModifiedFile", mensagemInputDto.getIsModifiedFile())
                .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());

        var instituicoesMensagem = this.dao.queryFactory()
                .selectFrom(mensagemInstituicao)
                .where(mensagemInstituicao.mensagemId.eq(storedMensagemId))
                .fetch();

        assertThat(instituicoesMensagem).isEmpty();
    }

    @Test
    @DisplayName("Deve criar mensagem ativa para instituições específicas com dados válidos")
    void storeMensagemAtivaParaInstituicoesEspecificasExpectSuccess() {
        var instituicao1 = this.instituicaoFactory.createRandom();
        var instituicao2 = this.instituicaoFactory.createRandom();

        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(2);
            m.instituicaoIds.set(List.of(instituicao1.getId(), instituicao2.getId()));
            m.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
            m.descricao.set("<div>Notificação para instituições específicas</div>");
        });

        var request = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .formParam("isModifiedFile", mensagemInputDto.getIsModifiedFile())
                .formParam("dataValidade", mensagemInputDto.getDataValidade().toString());

        mensagemInputDto.getInstituicaoIds().forEach(instituicaoId -> request.formParam("instituicaoIds", instituicaoId));

        var storedMensagemId = request
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());

        var instituicoesMensagem = this.dao.queryFactory()
                .selectFrom(mensagemInstituicao)
                .where(mensagemInstituicao.mensagemId.eq(storedMensagemId))
                .fetch();

        assertThat(instituicoesMensagem).hasSize(2);
        assertThat(instituicoesMensagem)
                .extracting(MensagemInstituicao::getInstituicaoId)
                .containsExactlyInAnyOrder(instituicao1.getId(), instituicao2.getId());
    }

    @Test
    @DisplayName("Deve criar mensagem inativa com dados válidos")
    void storeMensagemInativaExpectSuccess() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(1);
            m.instituicaoIds.set(List.of());
            m.dataValidade.set(null);
            m.descricao.set("<span>Mensagem inativa</span>");
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .formParam("isModifiedFile", mensagemInputDto.getIsModifiedFile())
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
        assertThat(storedMensagem.getDataValidade()).isNull();

        var instituicoesMensagem = this.dao.queryFactory()
                .selectFrom(mensagemInstituicao)
                .where(mensagemInstituicao.mensagemId.eq(storedMensagemId))
                .fetch();

        assertThat(instituicoesMensagem).isEmpty();
    }

    @Test
    @DisplayName("Não deve criar mensagem sem autorização")
    void storeMensagemWithoutAuthorizationExpectUnauthorized() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(2);
            m.instituicaoIds.set(List.of());
            m.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
            m.descricao.set("<p>Mensagem sem autorização</p>");
        });

        given()
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .formParam("isModifiedFile", mensagemInputDto.getIsModifiedFile())
                .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(401);
    }
}"

"@DatabaseTest
class MensagemAdminControllerIntegrationTest extends RestAssuredMockMvcTest {

