"@DatabaseTest
class MensagemAdminControllerIntegrationTest extends RestAssuredMockMvcTest {

 private static final String BASE_URL = "/api/admin/mensagens/";
 private final MensagemInputITDtoFactory mensagemInputITDtoFactory = new MensagemInputITDtoFactory();
 private final BridgeFaker faker = new BridgeFaker();

 @Autowired
 private MensagemFactory mensagemFactory;

 @Autowired
 private InstituicaoFactory instituicaoFactory;

 @Autowired
 private DAO dao;

 @Autowired
 private LDAPJwtFactory ldapJwtFactory;

 @Test
 @DisplayName("Deve atualizar mensagem com dados válidos para instituições específicas")
 void updateMensagemExpectSuccess() {
 var mensagemInDb = this.mensagemFactory.createRandom();
 var instituicao1 = this.instituicaoFactory.createRandom();
 var instituicao2 = this.instituicaoFactory.createRandom();

 var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
 m.titulo.set(this.faker.lorem().sentence());
 m.descricao.set("<p>" + this.faker.lorem().paragraph() + "</p>");
 m.situacaoMensagem.set(2);
 m.instituicaoIds.set(List.of(instituicao1.getId(), instituicao2.getId()));
 m.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
 m.isModifiedFile.set(Boolean.FALSE);
 });

 given()
 .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
 .contentType(MULTIPART_FORM_DATA_VALUE)
 .formParam("titulo", mensagemInputDto.getTitulo())
 .formParam("descricao", mensagemInputDto.getDescricao())
 .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
 .formParam("instituicaoIds", instituicao1.getId(), instituicao2.getId())
 .formParam("isModifiedFile", mensagemInputDto.getIsModifiedFile())
 .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
 .when()
 .put(BASE_URL + mensagemInDb.getId())
 .then()
 .statusCode(200);

 var updatedMensagem = this.dao.find(Mensagem.class, mensagemInDb.getId());

 assertThat(updatedMensagem).isNotNull();
 assertThat(updatedMensagem.getId()).isEqualTo(mensagemInDb.getId());
 assertThat(updatedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
 assertThat(updatedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
 assertThat(updatedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
 assertThat(updatedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());
 }

